'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import {
  Listbox as ListboxPrimitive,
  type CollectionItem,
  type ListboxRootComponent,
  type ListboxRootProps,
  type ListboxRootProviderComponent,
  type ListboxRootProviderProps,
  useListbox,
  useListboxContext,
  useListboxItemContext,
} from '@ark-ui/react/listbox';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef, ForwardedRef } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CheckIcon, SearchIcon } from '@/lib/moduix/icons/ui';
import { CloseButton } from '../close-button';
import styles from './Listbox.module.css';

const Listbox = forwardRef(function Listbox<T extends CollectionItem>(
  { className, ...props }: ListboxRootProps<T>,
  ref: ForwardedRef<ComponentRef<typeof ListboxPrimitive.Root>>,
) {
  return (
    <ListboxPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="listbox-root"
    />
  );
}) as ListboxRootComponent;

const ListboxRootProvider = forwardRef(function ListboxRootProvider<T extends CollectionItem>(
  { className, ...props }: ListboxRootProviderProps<T>,
  ref: ForwardedRef<ComponentRef<typeof ListboxPrimitive.RootProvider>>,
) {
  return (
    <ListboxPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="listbox-root-provider"
    />
  );
}) as ListboxRootProviderComponent;

const ListboxLabel = forwardRef<
  ComponentRef<typeof ListboxPrimitive.Label>,
  ComponentProps<typeof ListboxPrimitive.Label>
>(function ListboxLabel({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="listbox-label"
    />
  );
});

const ListboxInput = forwardRef<
  ComponentRef<typeof ListboxPrimitive.Input>,
  ComponentProps<typeof ListboxPrimitive.Input>
>(function ListboxInput({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.Input
      ref={ref}
      className={clsx(styles.input, className)}
      {...props}
      data-slot="listbox-input"
    />
  );
});

const ListboxFilter = forwardRef<HTMLDivElement, ComponentProps<'div'>>(function ListboxFilter(
  { className, children, ...props },
  ref,
) {
  return (
    <div ref={ref} className={clsx(styles.filter, className)} {...props} data-slot="listbox-filter">
      <SearchIcon data-slot="listbox-filter-icon" className={styles.filterIcon} />
      {children}
    </div>
  );
});

const ListboxClearTrigger = forwardRef<ComponentRef<typeof ark.button>, HTMLArkProps<'button'>>(
  function ListboxClearTrigger(
    { 'aria-label': ariaLabel = a11yLabels.clearSearch, className, ...props },
    ref,
  ) {
    return (
      <CloseButton
        ref={ref}
        aria-label={ariaLabel}
        className={clsx(styles.clearTrigger, className)}
        {...props}
        data-slot="listbox-clear-trigger"
      />
    );
  },
);

const ListboxContent = forwardRef<
  ComponentRef<typeof ListboxPrimitive.Content>,
  ComponentProps<typeof ListboxPrimitive.Content>
>(function ListboxContent({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="listbox-content"
    />
  );
});

const ListboxEmpty = forwardRef<
  ComponentRef<typeof ListboxPrimitive.Empty>,
  ComponentProps<typeof ListboxPrimitive.Empty>
>(function ListboxEmpty({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.Empty
      ref={ref}
      className={clsx(styles.empty, className)}
      {...props}
      data-slot="listbox-empty"
    />
  );
});

const ListboxItemGroup = forwardRef<
  ComponentRef<typeof ListboxPrimitive.ItemGroup>,
  ComponentProps<typeof ListboxPrimitive.ItemGroup>
>(function ListboxItemGroup({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.ItemGroup
      ref={ref}
      className={clsx(styles.itemGroup, className)}
      {...props}
      data-slot="listbox-item-group"
    />
  );
});

const ListboxItemGroupLabel = forwardRef<
  ComponentRef<typeof ListboxPrimitive.ItemGroupLabel>,
  ComponentProps<typeof ListboxPrimitive.ItemGroupLabel>
>(function ListboxItemGroupLabel({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.ItemGroupLabel
      ref={ref}
      className={clsx(styles.itemGroupLabel, className)}
      {...props}
      data-slot="listbox-item-group-label"
    />
  );
});

const ListboxItem = forwardRef<
  ComponentRef<typeof ListboxPrimitive.Item>,
  ComponentProps<typeof ListboxPrimitive.Item>
>(function ListboxItem({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="listbox-item"
    />
  );
});

const ListboxItemText = forwardRef<
  ComponentRef<typeof ListboxPrimitive.ItemText>,
  ComponentProps<typeof ListboxPrimitive.ItemText>
>(function ListboxItemText({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.ItemText
      ref={ref}
      className={clsx(styles.itemText, className)}
      {...props}
      data-slot="listbox-item-text"
    />
  );
});

const ListboxItemIndicator = forwardRef<
  ComponentRef<typeof ListboxPrimitive.ItemIndicator>,
  ComponentProps<typeof ListboxPrimitive.ItemIndicator>
>(function ListboxItemIndicator({ className, children, ...props }, ref) {
  return (
    <ListboxPrimitive.ItemIndicator
      ref={ref}
      className={clsx(styles.itemIndicator, className)}
      {...props}
      data-slot="listbox-item-indicator"
    >
      {children ?? <CheckIcon />}
    </ListboxPrimitive.ItemIndicator>
  );
});

const ListboxValueText = forwardRef<
  ComponentRef<typeof ListboxPrimitive.ValueText>,
  ComponentProps<typeof ListboxPrimitive.ValueText>
>(function ListboxValueText({ className, ...props }, ref) {
  return (
    <ListboxPrimitive.ValueText
      ref={ref}
      className={clsx(styles.valueText, className)}
      {...props}
      data-slot="listbox-value-text"
    />
  );
});

const ListboxItemTextContent = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function ListboxItemTextContent({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextContent, className)}
        {...props}
        data-slot="listbox-item-text-content"
      />
    );
  },
);

const ListboxItemTextIcon = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function ListboxItemTextIcon({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextIcon, className)}
        {...props}
        data-slot="listbox-item-text-icon"
      />
    );
  },
);

const ListboxItemTextLabel = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function ListboxItemTextLabel({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextLabel, className)}
        {...props}
        data-slot="listbox-item-text-label"
      />
    );
  },
);

const ListboxContext = ListboxPrimitive.Context;
const ListboxItemContext = ListboxPrimitive.ItemContext;

export {
  Listbox,
  ListboxClearTrigger,
  ListboxContent,
  ListboxContext,
  ListboxEmpty,
  ListboxFilter,
  ListboxInput,
  ListboxItem,
  ListboxItemContext,
  ListboxItemGroup,
  ListboxItemGroupLabel,
  ListboxItemIndicator,
  ListboxItemText,
  ListboxItemTextContent,
  ListboxItemTextIcon,
  ListboxItemTextLabel,
  ListboxLabel,
  ListboxRootProvider,
  ListboxValueText,
  useListbox,
  useListboxContext,
  useListboxItemContext,
};

export type {
  CollectionItem,
  ListboxContentProps,
  ListboxContextProps,
  ListboxEmptyProps,
  ListboxHighlightChangeDetails,
  ListboxInputProps,
  ListboxItemContextProps,
  ListboxItemGroupLabelProps,
  ListboxItemGroupProps,
  ListboxItemIndicatorProps,
  ListboxItemProps,
  ListboxItemTextProps,
  ListboxLabelProps,
  ListboxRootProps,
  ListboxRootProviderProps,
  ListboxScrollToIndexDetails,
  ListboxSelectionDetails,
  ListboxSelectionMode,
  ListboxValueChangeDetails,
  ListboxValueTextProps,
  ListCollection,
  UseListboxContext,
  UseListboxItemContext,
  UseListboxProps,
  UseListboxReturn,
} from '@ark-ui/react/listbox';

@layer moduix.components {
  .root {
    --_listbox-gap: var(--moduix-spacing-3);

    box-sizing: border-box;
    display: flex;
    width: var(--moduix-listbox-width, 16rem);
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--_listbox-gap);
    color: var(--moduix-color-foreground);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  /* A disabled root already dims its parts. */
  .root[data-disabled] :is(.input, .item) {
    opacity: 1;
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
  }

  .input {
    box-sizing: border-box;
    width: 100%;
    min-height: var(--moduix-size-md);
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: inherit;
    font: inherit;
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &:disabled {
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
    }
  }

  .filter {
    box-sizing: border-box;
    position: relative;
    width: 100%;
  }

  .filterIcon {
    position: absolute;
    top: 50%;
    inset-inline-start: var(--moduix-spacing-3);
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);
    pointer-events: none;
    transform: translateY(-50%);
  }

  /* Room for the icon and the clear action, each with an 8px gap before the text. */
  .filter .input {
    padding-inline: calc(
        var(--moduix-spacing-3) + var(--moduix-spacing-4) + var(--moduix-spacing-2)
      )
      calc(var(--moduix-spacing-3) + var(--moduix-size-xs) + var(--moduix-spacing-2));

    &:focus-visible {
      outline-color: transparent;
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-size-xs);

    position: absolute;
    top: 50%;
    inset-inline-end: var(--moduix-spacing-3);
    transform: translateY(-50%);
  }

  /* A filter right before the content joins it into one surface with a neutral divider. */
  .filter:has(+ .content) .input {
    border-bottom: 0;
    border-bottom-right-radius: 0;
    border-bottom-left-radius: 0;
  }

  .filter + .content {
    margin-block-start: calc(-1 * var(--_listbox-gap));
    border-top-left-radius: 0;
    border-top-right-radius: 0;

    &:focus-visible {
      outline-color: transparent;
    }
  }

  .filter:has(.input:focus-visible, + .content:focus-visible) {
    .input {
      border-color: var(--moduix-color-ring);
    }

    + .content {
      border-inline-color: var(--moduix-color-ring);
      border-bottom-color: var(--moduix-color-ring);
    }
  }

  .content {
    box-sizing: border-box;
    display: flex;
    min-height: 0;
    max-height: var(--moduix-listbox-content-max-height, 14rem);
    flex-direction: column;
    overflow-x: hidden;
    overflow-y: auto;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    background-color: var(--moduix-color-background);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    scrollbar-gutter: stable;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &[data-layout='grid'] {
      display: grid;
      grid-template-columns: repeat(var(--column-count), minmax(0, 1fr));
      gap: var(--moduix-spacing-1);
      padding: var(--moduix-spacing-2);
    }

    &[data-orientation='horizontal']:not([data-layout='grid']) {
      max-height: none;
      flex-direction: row;
      gap: var(--moduix-spacing-2);
      overflow-x: auto;
      overflow-y: hidden;
      padding-inline: var(--moduix-spacing-1);
    }
  }

  .empty {
    padding-block: var(--moduix-spacing-1);
    padding-inline: var(--moduix-spacing-3);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-align: center;
  }

  .itemGroup {
    display: flex;
    flex-direction: column;

    & + & {
      margin-block-start: var(--moduix-spacing-2);
    }
  }

  .itemGroupLabel {
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-spacing-2);
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
    user-select: none;
  }

  /* The second column reserves indicator space, so selecting an item does not shift its text. */
  .item {
    box-sizing: border-box;
    display: grid;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    grid-template-columns: minmax(0, 1fr) var(--moduix-spacing-4);
    align-items: center;
    gap: var(--moduix-spacing-2);
    margin-inline: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    outline: 0;
    user-select: none;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    @media (hover: hover) {
      &:where(:not([data-disabled]):hover) {
        background-color: var(--moduix-color-accent);
        color: var(--moduix-color-accent-foreground);
      }
    }

    &[data-highlighted] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &[data-disabled] {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
      cursor: default;
    }

    /* Grid items show selection with a neutral fill instead of the indicator column. */
    &[data-layout='grid'] {
      min-width: 0;
      grid-template-columns: minmax(0, 1fr);
      justify-items: center;
      margin-inline: 0;
      text-align: center;

      &[data-selected] {
        background-color: var(--moduix-color-muted);
        color: var(--moduix-color-foreground);
      }
    }

    &[data-orientation='horizontal']:not([data-layout='grid']) {
      width: 11rem;
      min-width: 11rem;
      align-items: flex-start;
    }
  }

  .itemText,
  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }

    /* Ark also sets `hidden`; this keeps the space when an app reset does not hide it. */
    &[data-state='unchecked'] {
      visibility: hidden;
    }
  }

  .valueText {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .itemTextContent {
    display: inline-flex;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }
}
